class Solution {
    public int minTaps(int n,int[] ranges){
        int[] reach=new int[n+1];
        for(int i=0;i<=n;i++){
            int left=Math.max(0,i-ranges[i]),right=Math.min(n,i+ranges[i]);
            reach[left]=Math.max(reach[left],right);
        }
        int taps=0,currentEnd=0,farthest=0;
        for(int position=0;position<n;position++){
            farthest=Math.max(farthest,reach[position]);
            if(position==currentEnd){
                if(farthest<=position)return -1;
                taps++;
                currentEnd=farthest;
                if(currentEnd>=n)return taps;
            }
        }
        return taps;
    }
}

